def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """

    # Split the string into words and count occurrences of each word (letter)
    letter_counts = {word: test.split().count(word) for word in set(test.split())}

    # Find maximum occurrence
    max_occurrence = max(letter_counts.values()) if letter_counts else 0

    # Return dictionary with letters having the maximum occurrence
    return {k: v for k, v in letter_counts.items() if v == max_occurrence}
```
